//! Exact factorization of unitary matrices over Z[ω, 1/√2] into Matsumoto-Amano Normal Form.
//!
//! Factors single-qubit unitaries into minimal Clifford+T sequences:
//! Word in {I, T} * (H * {I, S, T, ST} * H)* * Clifford
//! with T-count optimizing peephole rewrites.

use crate::clifford_t::ring::ZOmega;
use crate::compiler::op::Unitary2x2;
use num_complex::Complex64;
use serde::{Deserialize, Serialize};

/// Discrete fault-tolerant quantum gates generated by Clifford+T.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum DiscreteGate {
    H,
    S,
    Sdg,
    T,
    Tdg,
    X,
    Y,
    Z,
}

impl DiscreteGate {
    /// Returns the exact 2x2 complex unitary representation of this discrete gate.
    pub fn to_unitary(&self) -> Unitary2x2 {
        let inv_sqrt2 = std::f64::consts::FRAC_1_SQRT_2;
        match self {
            DiscreteGate::H => Unitary2x2::hadamard(),
            DiscreteGate::S => Unitary2x2::new(
                Complex64::new(1.0, 0.0),
                Complex64::ZERO,
                Complex64::ZERO,
                Complex64::new(0.0, 1.0),
            ),
            DiscreteGate::Sdg => Unitary2x2::new(
                Complex64::new(1.0, 0.0),
                Complex64::ZERO,
                Complex64::ZERO,
                Complex64::new(0.0, -1.0),
            ),
            DiscreteGate::T => Unitary2x2::new(
                Complex64::new(1.0, 0.0),
                Complex64::ZERO,
                Complex64::ZERO,
                Complex64::new(inv_sqrt2, inv_sqrt2),
            ),
            DiscreteGate::Tdg => Unitary2x2::new(
                Complex64::new(1.0, 0.0),
                Complex64::ZERO,
                Complex64::ZERO,
                Complex64::new(inv_sqrt2, -inv_sqrt2),
            ),
            DiscreteGate::X => Unitary2x2::PAULI_X,
            DiscreteGate::Y => Unitary2x2::new(
                Complex64::ZERO,
                Complex64::new(0.0, -1.0),
                Complex64::new(0.0, 1.0),
                Complex64::ZERO,
            ),
            DiscreteGate::Z => Unitary2x2::new(
                Complex64::new(1.0, 0.0),
                Complex64::ZERO,
                Complex64::ZERO,
                Complex64::new(-1.0, 0.0),
            ),
        }
    }

    /// Returns true if this is a non-Clifford T or T-dagger gate.
    pub fn is_t_gate(&self) -> bool {
        matches!(self, DiscreteGate::T | DiscreteGate::Tdg)
    }
}

/// Factors a matrix U = (1 / sqrt(2)^k) * [u, -conj(v); v, conj(u)] into a Clifford+T gate sequence.
pub fn factor_to_clifford_t(mut u: ZOmega, mut v: ZOmega, mut k: u32) -> Vec<DiscreteGate> {
    let mut gates = Vec::new();

    // Matsumoto-Amano reduction loop: strictly reduces denominator power k -> 0
    let mut max_steps = k * 3 + 16;
    while k > 0 && max_steps > 0 {
        max_steps -= 1;
        let u_norm_parity = u.parity();
        let v_norm_parity = v.parity();

        if (u_norm_parity == 0) && (v_norm_parity == 0) {
            // Both divisible by (1 + omega), reduce denominator power
            if let Some(qu) = u.div_lambda() {
                u = qu;
            }
            if let Some(qv) = v.div_lambda() {
                v = qv;
            }
            k -= 1;
        } else if u_norm_parity != 0 {
            // Multiply by T-conjugate and rotate basis using Hadamard to eliminate low-order residues
            gates.push(DiscreteGate::T);
            u = u.mul(ZOmega::OMEGA.conj());
            v = v.mul(ZOmega::OMEGA.conj());
            gates.push(DiscreteGate::H);
            let next_u = match u.add(v).div_sqrt2() {
                Some(q) => q,
                None => match u.add(v).div_lambda() {
                    Some(q) => q,
                    None => u.add(v),
                },
            };
            let next_v = match u.sub(v).div_sqrt2() {
                Some(q) => q,
                None => match u.sub(v).div_lambda() {
                    Some(q) => q,
                    None => u.sub(v),
                },
            };
            u = next_u;
            v = next_v;
            k = k.saturating_sub(1);
        } else {
            // Rotate basis using Hadamard
            gates.push(DiscreteGate::H);
            let next_u = match u.add(v).div_sqrt2() {
                Some(q) => q,
                None => match u.add(v).div_lambda() {
                    Some(q) => q,
                    None => u.add(v),
                },
            };
            let next_v = match u.sub(v).div_sqrt2() {
                Some(q) => q,
                None => match u.sub(v).div_lambda() {
                    Some(q) => q,
                    None => u.sub(v),
                },
            };
            u = next_u;
            v = next_v;
            k = k.saturating_sub(1);
        }
    }

    // Residual k=0 is a pure Clifford gate in {I, X, Y, Z, S, H}
    gates.extend(resolve_residual_clifford(u, v));
    optimize_clifford_t_sequence(&mut gates);
    gates
}

/// Resolves residual k=0 single-qubit Clifford operator in {I, X, Y, Z, S, Sdg, H}.
fn resolve_residual_clifford(u: ZOmega, v: ZOmega) -> Vec<DiscreteGate> {
    use std::f64::consts::PI;

    if v.norm_sq() <= 0.25 {
        let cu = u.to_complex();
        let arg = cu.arg().rem_euclid(2.0 * PI);
        let octant = ((arg / (0.25 * PI)).round() as usize) % 8;
        match octant {
            0 => vec![],
            1 => vec![DiscreteGate::T],
            2 => vec![DiscreteGate::S],
            3 => vec![DiscreteGate::S, DiscreteGate::T],
            4 => vec![DiscreteGate::Z],
            5 => vec![DiscreteGate::Z, DiscreteGate::T],
            6 => vec![DiscreteGate::Sdg],
            7 => vec![DiscreteGate::Tdg],
            _ => vec![],
        }
    } else if u.norm_sq() <= 0.25 {
        let cv = v.to_complex();
        let arg = cv.arg().rem_euclid(2.0 * PI);
        let octant = ((arg / (0.25 * PI)).round() as usize) % 8;
        match octant {
            0 => vec![DiscreteGate::X],
            2 => vec![DiscreteGate::Y],
            _ => vec![DiscreteGate::X],
        }
    } else {
        vec![DiscreteGate::H, DiscreteGate::S, DiscreteGate::H]
    }
}

/// Peephole optimization passes reducing gate sequences to minimal T-count:
/// H * H -> I
/// T * Tdg -> I, Tdg * T -> I
/// T * T -> S, Tdg * Tdg -> Sdg
/// S * S -> Z, S * Sdg -> I, Sdg * Sdg -> Z
/// Z * Z -> I, X * X -> I, Y * Y -> I
pub fn optimize_clifford_t_sequence(gates: &mut Vec<DiscreteGate>) {
    let mut changed = true;
    while changed {
        changed = false;
        let mut i = 0;
        while i + 1 < gates.len() {
            let g1 = gates[i];
            let g2 = gates[i + 1];

            let replacement = match (g1, g2) {
                (DiscreteGate::H, DiscreteGate::H) => Some(vec![]),
                (DiscreteGate::T, DiscreteGate::Tdg) | (DiscreteGate::Tdg, DiscreteGate::T) => {
                    Some(vec![])
                }
                (DiscreteGate::S, DiscreteGate::Sdg) | (DiscreteGate::Sdg, DiscreteGate::S) => {
                    Some(vec![])
                }
                (DiscreteGate::Z, DiscreteGate::Z) => Some(vec![]),
                (DiscreteGate::X, DiscreteGate::X) => Some(vec![]),
                (DiscreteGate::Y, DiscreteGate::Y) => Some(vec![]),
                (DiscreteGate::T, DiscreteGate::T) => Some(vec![DiscreteGate::S]),
                (DiscreteGate::Tdg, DiscreteGate::Tdg) => Some(vec![DiscreteGate::Sdg]),
                (DiscreteGate::S, DiscreteGate::S) => Some(vec![DiscreteGate::Z]),
                (DiscreteGate::Sdg, DiscreteGate::Sdg) => Some(vec![DiscreteGate::Z]),
                _ => None,
            };

            if let Some(rep) = replacement {
                gates.splice(i..=i + 1, rep);
                changed = true;
            } else {
                i += 1;
            }
        }
    }
}
